digital={
 'goalId':GUIDED,'expectationId':'hb-own-experimental-electronic-record','sourceOrdinals':[23,65],
 'scope':pair('Zusatz nur bei der HB-SekII-Quellenroute für digitale Erfassung. Die vorhandenen angeleiteten Fälle und ihre bisherigen Sicherheits-/Kontroll-/Auswertungspflichten bleiben unverändert. Außerhalb dieses Quellscopes keine zusätzliche digitale Abschlussbedingung.','Addition only for the HB upper-secondary source route requiring digital recording. Existing guided cases and all safety/control/interpretation duties remain. No additional digital completion condition outside this source scope.'),
 'material':pair('Verwende einen der beiden vorhandenen, tatsächlich betreut durchgeführten Fälle: Leitfähigkeitsvergleich ODER Zuckerauflösung. Die vollständigen örtlich freizugebenden Anleitungen, Geräteprüfungen, Kontrollen und bisherigen Transfers stehen im lokalen RETAINED-Material. Zusätzlich steht ein geeignetes lokales elektronisches Tabellen-/Textwerkzeug mit leerem Rohprotokoll bereit. Es enthält keine angeblichen eigenen Messwerte. Geräteablesungen dürfen manuell eingetragen werden. Eine geeignete automatische Übertragung ist ebenfalls möglich; ein Digitaldisplay allein mit ausschließlich Papierprotokoll ist keine elektronische Aufzeichnung. Die tatsächliche Experiment-/Probenzuordnung muss erkennbar sein.','Use one of the two existing actually supervised cases: conductivity comparison OR sugar dissolution. Complete locally authorised procedures, instrument checks, controls and retained transfers are in the local RETAINED material. An appropriate local electronic table/text tool with a blank raw-record template is additionally available. It contains no purported own measurements. Instrument readings may be entered manually. Suitable automatic transfer is also possible; a digital display recorded only on paper is not electronic recording. Actual experiment/sample identification must remain clear.'),
 'task':pair('Erfasse die tatsächlich beobachteten experimentellen Rohwerte deiner gewählten Untersuchung selbst in einem elektronischen Protokoll. Ordne jede Zeile eindeutig der Probe bzw. dem Messpunkt/Ansatz und der tatsächlichen Durchführung zu; notiere Wert, Einheit und die schon verlangten Bedingungen/Kontrollen. Überträgst du zunächst sichere Papiernotizen, bewahre ihren Bezug und prüfe die elektronische Übertragung. Kennzeichne fehlende Werte, Überlauf, Abweichung und spätere Korrektur ehrlich. Bewahre das tatsächliche elektronische Produkt oder einen prüfbaren Export auf und zeige an deinem Protokoll, welcher Messwert welchen Befund stützt. Alle vorhandenen Sicherheits-, Wiederholungs-, Hypothesen- und Transferaufträge gelten weiter. Eine geeignete zusammenhängende eigene Reihe genügt für die Digitalergänzung; es gibt keine zusätzliche Zahl von Dateien oder Versuchsläufen.','Record the actually observed experimental raw values from your chosen investigation yourself in an electronic record. Identify each row with its sample or measurement point/run and actual execution; record value, unit and the already required conditions/controls. If safe paper notes are transcribed, preserve their relationship and check the electronic transcription. Honestly label missing values, over-range, deviations and later corrections. Retain the actual electronic product or a verifiable export and use your record to show which measurement supports which finding. All existing safety, repeat, hypothesis and transfer tasks remain. One suitable coherent own series suffices for this digital addition; there is no extra quota of files or experimental runs.'),
 'expected':pair('Erwartet wird ein tatsächlich selbst geführtes elektronisches Rohprotokoll mit echten Messwerten und nachvollziehbaren Einheiten/Proben-/Bedingungsbezügen. Es wird kein Sollwert eingesetzt, um einen Prüf- oder Hypothesenbefund passend zu machen. Leitfähigkeitsroute: Blank/Probe, reale Temperatur, Bereich/Modus und vorgeschriebene Standardprüfung bleiben unterscheidbar; der Standard-Etikettbereich ist Referenz, kein eigener Messwert. Auflösungsroute: Ansatz/Körnung, tatsächliche Starttemperatur, gemessene Dauer und Wiederholung bleiben zugeordnet. Eine manuelle Eingabe ist gültig, wenn die Einträge wirklich auf den eigenen beobachteten Experimentdaten beruhen. Modell-/Referenzwerte allein oder eine leere Vorlage erfüllen die Pflicht nicht.','Expected is an actually self-maintained electronic raw record containing real measurements with traceable units/sample/condition relationships. Do not insert expected values to force a successful check or hypothesis. Conductivity route: distinguish blank/sample, actual temperature, range/mode and required standard check; the standard label interval is reference information, not an own reading. Dissolution route: identify run/grain size, actual starting temperature, measured duration and repeat. Manual entry is valid when genuinely based on the learner’s observed experimental data. Model/reference values alone or an empty template do not satisfy this duty.'),
 'blankTemplate':{'header':pair('Durchführung/Datum __; eigene beobachtete Handlung __; freigegebene Methode __; Werkzeug/Datei __; Herkunft früherer Notizen __','Execution/date __; own observed action __; authorised method __; tool/file __; origin of earlier notes __'),'columns':pair('Zeile | Probe/Ansatz/Messpunkt | Rohwert | Einheit | tatsächliche Bedingung/Kontrolle | Beobachter/Datenerfasser | Abweichung/Korrekturbezug','Row | sample/run/measurement point | raw value | unit | actual condition/control | observer/recorder | deviation/correction reference'),'rows':[None,None,None],'allMeasurementCellsIntentionallyEmpty':True},
 'rubric':[pair('Tatsächliche sichere Untersuchung und Herkunft der eigenen Rohwerte bleiben belegt; kein fiktiver Durchführungserfolg.','Actual safe investigation and origin of own raw values remain evidenced; no fictional successful performance.'),pair('Eine tatsächlich vom Lernenden geführte elektronische Aufzeichnung enthält die echte Reihe mit korrekten Einheiten und eindeutiger Proben-/Messpunktzuordnung.','An actual electronic record maintained by the learner contains the real series with correct units and unambiguous sample/point identification.'),pair('Referenz-/Modelldaten, Übertragungen, Fehlstellen und Korrekturen werden von originalen eigenen Messwerten getrennt.','Reference/model values, transcriptions, missing entries and corrections are distinguished from original own measurements.'),pair('Die bisherigen Kontroll-, Unsicherheits-, Hypothesen- und frischen Transferleistungen sind erfüllt; elektronische Aufzeichnung ersetzt keine davon.','All retained control, uncertainty, hypothesis and fresh-transfer duties are met; electronic recording replaces none of them.')],
 'noAdditionalImplementationQuota':pair('Keine Pflicht zu Sensorkopplung, automatischem Export, Zeit-Synchronisation, Cloud, bestimmtem Dateiformat oder eigener Durchführung aller denkbaren Arbeitsschritte. Die bereits methodisch nötige Zeitmessung im Auflösungsfall bleibt erhalten.','No requirement for sensor coupling, automated export, time synchronisation, cloud, a particular file format or personally performing every possible operation. The time measurement already needed by the dissolution method remains.')}

three={
 'goalId':REP,'expectationId':'hb-digital-three-observation-levels','sourceOrdinals':[67],
 'scope':pair('Zusatz nur bei HB-SekII-Drei-Ebenen-Quellenpflicht. Ergänzt den vorhandenen NaCl-Prozessdarstellungsfall; der Betriebsdaten-/Bezugsgrößenfall und alle bisherigen Aufgaben bleiben erhalten. Keine neue allgemeine Modellierungs- oder Mikroskopier-Voraussetzung.','Addition only for the HB upper-secondary three-level source duty. Extends the existing NaCl process-representation case; the operating-data/reference-quantity case and all previous tasks remain. No new general modelling or microscopy prerequisite.'),
 'material':pair('Derselbe NaCl-Lösungsvorgang wird durch drei ausdrücklich zu unterscheidende Informationskarten ergänzt. Alle Karten sind Autorenmodelle zur Darstellung, keine eigenen oder behaupteten realen Mikroskopaufnahmen. Makro-Karte: Im Becher sind zunächst weiße Salzkörner sichtbar; nach vollständigem Lösen in Wasser ist die Lösung klar. Das vorhandene Leitfähigkeitsbeispiel wird über bewegliche Ladungsträger erklärt, nicht durch neu erzeugte Ladung. Mikro-Karte: Zwei beschriebene modellhafte Lichtmikroskop-Sichtfelder haben jeweils 500 µm Breite. M1 zeigt einen eckigen, 100 µm breiten Salzkristall; M2 nach vollständiger Auflösung keinen optisch auflösbaren Kristall. Die Größen sind gesetzte Zeichnungsmaße, keine Messdaten. Die Mikroskopansicht kann die Kristallkontur, nicht einzelne Na+/Cl−-Ionen zeigen. Submikro-Karte: Vorher ein Gitterausschnitt mit vier Na+ und vier Cl−; nachher dieselben vier Na+ und vier Cl− beweglich im Wasser verteilt. Es handelt sich um ein stark vereinfachtes Teilchenmodell ohne realen Atommaßstab, kein Foto. Die Lösung bleibt insgesamt neutral. Die Formel NaCl(s)→Na+(aq)+Cl−(aq) ist eine zusätzliche symbolische Kurzschreibweise und keine vierte Beobachtungsebene.','The same NaCl dissolution process is extended by three information cards to be explicitly distinguished. All cards are authored representation models, not own or purported real microscope images. Macro card: white salt grains are initially visible in the beaker; after complete dissolution in water the solution is clear. Explain the retained conductivity example through mobile charge carriers, not newly created charge. Micro card: two described model light-microscope fields are each 500 µm wide. M1 shows an angular salt crystal 100 µm wide; M2 after complete dissolution shows no optically resolvable crystal. These sizes are assigned drawing dimensions, not measurements. The microscope view can show the crystal outline, not individual Na+/Cl− ions. Submicro card: a lattice fragment with four Na+ and four Cl− before; the same four Na+ and four Cl− mobile and dispersed in water after. This is a strongly simplified particle model without a real atomic scale, not a photograph. The solution remains neutral overall. NaCl(s)→Na+(aq)+Cl−(aq) is supplementary symbolic shorthand, not a fourth observation level.'),
 'task':pair('Überführe den vorhandenen NaCl-Text und die drei Karten tatsächlich in eine geeignete digitale Darstellung für die vorgegebene Zielgruppe. Ein zusammenhängendes Dokument mit verbundenen Ansichten ist möglich. Stelle makroskopischen Stoffzustand, mikroskopisch auflösbare Kristallkontur und submikroskopische Ionenverteilung jeweils erkennbar dar, beschrifte Ebene, Herkunft und Modellgrenze und begründe ihre Verknüpfung. Zeichnen mit Standardformen, eine passend beschriftete Überarbeitung geeigneter Vorlagen oder andere geeignete digitale Darstellung ist zulässig; eigene Programmierung ist nicht erforderlich. Die Mikroskopansicht darf nicht durch eine Reaktionsformel oder ein Ionenbild ersetzt werden. Bewahre dein tatsächliches digitales Arbeitsprodukt auf. Bearbeite danach die bereits verlangte Anpassung für ein Oberstufenprotokoll; Chemie und Herkunft bleiben unverändert.','Actually transform the retained NaCl text and three cards into a suitable digital representation for the given audience. One coherent document with linked views is possible. Make the macroscopic material state, microscopically resolvable crystal outline and submicroscopic ion distribution each recognisable; label level, origin and model limitation and justify their connection. Standard-shape drawing, appropriately labelled adaptation of suitable templates or another suitable digital representation is allowed; programming is not required. Do not replace the microscope view with a reaction formula or ion picture. Retain your actual digital work product. Then perform the already required upper-secondary record adaptation, preserving chemistry and origin.'),
 'expected':pair('Eigenes digitales Produkt verknüpft sichtbare Körner/klare Lösung mit den beiden modellierten Lichtmikroskopfeldern und dem korrekt ladungsbilanzierten Gitter-/Lösungsmodell. M1-Kristallbreite ist ein Fünftel der Feldbreite; ein Maßstabsbalken ist als Modellmaß gekennzeichnet. M2 ohne Kristall beweist kein Verschwinden der Ionen. Einzelne Ionen sind nur im submikroskopischen Modell zu sehen, nicht als tatsächlich im Lichtmikroskop aufgelöste Punkte. Vorher/nachher bleiben je vier positive und vier negative Ionen; Wasser löst das Gitter, erzeugt kein Na-Metall/H2 oder Nettoladung. Symbolische Gleichung erklärt das Schema, ersetzt aber keine Ebene. Modellherkunft, vereinfachte Hydratation und fehlende reale Geschwindigkeits-/3D-Information werden genannt. Tatsächliche digitale Bearbeitung und adressatengerechte Erklärung müssen sichtbar sein; eine fremde fertige Folie ohne eigenen Darstellungsbeitrag reicht nicht.','The own digital product links visible grains/clear solution with the two model light-microscope fields and the correctly charge-balanced lattice/solution model. M1 crystal width is one fifth of field width; any scale bar is labelled as a model dimension. No crystal in M2 does not prove disappearance of ions. Individual ions appear only in the submicroscopic model, not as points actually resolved by light microscopy. Four positive and four negative ions remain before/after; water dissolves the lattice and creates no Na metal/H2 or net charge. Symbolic equation explains the scheme but replaces no level. Identify model origin, simplified hydration and absent real rate/3D information. Actual digital work and audience-appropriate explanation must be visible; somebody else’s completed slide without an own representation contribution is insufficient.'),
 'blankTemplate':{'headings':pair('Makro: Stoffbeobachtung __ | Mikro: Lichtmikroskop-Sichtfeld M1/M2 __ | Submikro: Ionenmodell __ | Verbindung und Grenze __','Macro: material observation __ | Micro: light-microscope field M1/M2 __ | Submicro: ion model __ | connection and limitation __'),'learnerProduct':None,'actualPerformanceClaimed':False},
 'rubric':[pair('Tatsächliche eigene digitale Darstellung zeigt alle drei benannten Ebenen an diesem ausgewählten Beispiel; nicht zwingend drei Dateien oder Einzelaufgaben.','Actual own digital representation shows all three named levels in this selected example; three files or separate tasks are not required.'),pair('Die mikroskopische Ebene stellt auflösbare Kristallkonturen mit Modellmaß dar und wird weder atomar noch bloß symbolisch umgedeutet.','The microscopic level represents resolvable crystal outlines with model dimensions and is neither reinterpreted atomically nor merely symbolically.'),pair('Stoff-/Teilchenebene, Ionenzahl, Gesamtladung und Zustände bleiben korrekt; kein falscher Nachweis realer Ionenbilder oder eigener Messdaten.','Material/particle levels, ion counts, total charge and states remain correct; no false claim of real ion images or own measurements.'),pair('Darstellungswahl, Zielgruppenanpassung, erhaltene Aussagen und Grenzen werden selbst begründet; bestehende Betriebsdaten-/Bezugsgrößenpflichten bleiben bestehen.','Representation choice, audience adaptation, preserved claims and limits are justified by the learner; retained operating-data/reference-quantity duties remain.')],
 'freshTransfer':pair('Im bereits verlangten Oberstufenprotokoll wird die Formelschreibweise ergänzt. Begründe ausdrücklich, warum diese präzisere Symbolik das Mikro-Sichtfeld nicht ersetzt und warum fehlende sichtbare Kristalle keine ionenfreie Lösung belegen.','In the already required upper-secondary record adaptation add the formula notation. Explicitly justify why this more precise symbolism does not replace the microscopic field and why absence of visible crystals does not establish an ion-free solution.')}

def successor(goalid,addition,apply_case_ids):
    old=OLD[goalid]['wholeP']['profile'];new=copy.deepcopy(old);eid=addition['expectationId']
    new['expectations'].append({'id':eid,'essentialUnderstandingDe':addition['scope']['de'],'essentialUnderstandingEn':addition['scope']['en'],'observablePerformanceDe':addition['expected']['de'],'observablePerformanceEn':addition['expected']['en']})
    new['coverageExpectations']['requiredExpectationIds'].append(eid)
    new['variationAxes'].append({'id':eid+'-scope-and-transfer','textDe':addition.get('freshTransfer',addition['noAdditionalImplementationQuota'] if 'noAdditionalImplementationQuota' in addition else addition['scope'])['de'],'textEn':addition.get('freshTransfer',addition['noAdditionalImplementationQuota'] if 'noAdditionalImplementationQuota' in addition else addition['scope'])['en']})
    for case in new['applicationCaseBriefs']:
        if case['id'] in apply_case_ids:
            for key,section,lang in [('taskDemandDe','task','de'),('taskDemandEn','task','en'),('expectedPerformanceDe','expected','de'),('expectedPerformanceEn','expected','en')]:case[key]+='\n\n'+addition['scope'][lang]+'\n'+addition[section][lang]
    return new

guide=successor(GUIDED,digital,[x['id'] for x in OLD[GUIDED]['wholeP']['profile']['applicationCaseBriefs']])
